        let at = self.here();
        self.emit(I::JumpIfZero { local, target: 0 })?;
        Ok(at)
    }
    fn jump(&mut self) -> Result<usize> {
        let at = self.here();
        self.emit(I::Jump { target: 0 })?;
        Ok(at)
    }
