pub(crate) fn locals(&self) -> usize {
    let reg = |t: &TextRef| match *t {
        TextRef::Cell(_) => 0,
        TextRef::Element { index, .. } => usize::from(index) + 1,
    };
    match self {
        Self::ArrayFile { path, local, .. } => reg(path).max(usize::from(*local) + 1),
        Self::Midi {
            action,
            args,
            local,
            text,
        } => (usize::from(*args) + action.arguments())
            .max(usize::from(*local) + 1)
            .max(text.as_ref().map_or(0, reg)),
        Self::Waveform { args, local, .. } =>
            (usize::from(*args) + 4).max(usize::from(*local) + 1),
        Self::MidiFilename { text } => reg(text),
        Self::Real { lhs, rhs, .. }
        | Self::CompareReal { lhs, rhs, .. }
        | Self::Integer { lhs, rhs, .. }
        | Self::Random { lhs, rhs } => usize::from(*lhs.max(rhs)) + 1,
        Self::RealUnary { local, .. }
        | Self::WaitMidi { local }
        | Self::IntegerToReal { local }
        | Self::RealToInteger { local }
        | Self::ReadWidgetDropCount { local, .. }
        | Self::ReadCallbackUiId { local }
        | Self::ReadWidgetEventParameter { local }
        | Self::ReadWidgetInteraction { local, .. }
        | Self::ReadHost { local, .. }
        | Self::ReadClock { local, .. }
        | Self::ReadTimer { local } => usize::from(*local) + 1,
        Self::ReadWidgetDropText { index, text, .. } => {
            (usize::from(*index) + 1).max(reg(text))
        }
        Self::FileName { ui, format, text } => {
            (usize::from(*ui.max(format)) + 1).max(reg(text))
        }
        Self::TextProperty { key, text, .. } => (usize::from(*key) + 4).max(reg(text)),
        Self::TimeConversion { local, .. } => usize::from(*local) + 1,
        Self::EngineParameter { address, local, .. } => {
            (usize::from(*address) + 4).max(usize::from(*local) + 1)
        }
        Self::ZoneParameter {
            zone,
            parameter,
            local,
            ..
        } => usize::from((*zone).max(*parameter).max(*local)) + 1,
        Self::EngineDisplay {
            address,
            value,
            text,
        } => (usize::from(*address) + 4)
            .max(value.map_or(0, |v| usize::from(v) + 1))
            .max(reg(text)),
        Self::EngineLookup {
            group,
            owner,
            text,
            local,
            ..
        } => usize::from(*group.max(owner).max(local)) + 1 + reg(text),
        Self::Purge { group, local, .. } => usize::from(*group.max(local)) + 1,

fn behavior_bank(&self, id: BehaviorId) -> Result<&ScriptBank, Error> {
    let c = *self.behaviors.get(id.0).ok_or(Error::StaleHandle)?;
    let plan = self.behavior_plan(c.owner)?;
    let generation = self.plans.get(plan.0).ok_or(Error::StaleHandle)?;
    let instance = generation.prepared.programs[c.program]
        .script_instance
        .ok_or(Error::InvalidInput)?;
    generation
        .scripts
        .get(usize::from(instance.0))
        .ok_or(Error::InvalidInput)
}

fn behavior_bank_mut(&mut self, id: BehaviorId) -> Result<&mut ScriptBank, Error> {
    let c = *self.behaviors.get(id.0).ok_or(Error::StaleHandle)?;
    let plan = self.behavior_plan(c.owner)?;
    let generation = self.plans.get_mut(plan.0).ok_or(Error::StaleHandle)?;
    let instance = generation.prepared.programs[c.program]
        .script_instance
        .ok_or(Error::InvalidInput)?;
    // ponytail: text/store writes conservatively invalidate snapshots; filter their
    // addresses too if measured text-heavy callbacks still copy large arrays.
    generation.script_revision = generation.script_revision.wrapping_add(1);
    generation
        .scripts
        .get_mut(usize::from(instance.0))
        .ok_or(Error::InvalidInput)
}

fn reg(&self, id: BehaviorId, local: u16) -> Result<i64, Error> {
    self.behavior_locals
        .get(id.0.index * self.behavior_stride + usize::from(local))
        .copied()
        .ok_or(Error::InvalidInput)
}

fn set_reg(&mut self, id: BehaviorId, local: u16, value: i64) -> Result<(), Error> {
    *self
        .behavior_locals
        .get_mut(id.0.index * self.behavior_stride + usize::from(local))
        .ok_or(Error::InvalidInput)? = value;
    Ok(())
}

pub fn new(code: Vec<Instruction>) -> Result<Self, Error> {
    let mut locals = 0;
    let mut note_cells = 0;
    let mut script_cells = 0;
    let (mut script_texts, mut text_constants) = (0, 0);
    for op in &code {
        if let Instruction::Op(op) = op {
            locals = locals.max(op.locals());
            let (cells, constants) = op.texts()?;
            script_texts = script_texts.max(cells);
            text_constants = text_constants.max(constants);
            match *op {
                super::ops::Op::Call { target } if target as usize > code.len() => {
                    return Err(Error::InvalidInput);
                }
                super::ops::Op::Emit { count, .. }
                    if usize::from(count) > super::ops::EFFECT_ARGS =>
                {
                    return Err(Error::InvalidInput);
                }
                _ => {}
            }
        }
        match *op {
            Instruction::Play {
                velocity: Velocity::Scale(value) | Velocity::Fixed(value),
                ..
            } if !value.is_finite() || !(0.0..=1.0).contains(&value) => {
                return Err(Error::InvalidInput);
            }
            Instruction::Jump { target } | Instruction::JumpIfZero { target, .. }
                if target > code.len() =>
            {
                return Err(Error::InvalidInput);
            }
            _ => {}
        }
        if let Instruction::SetLocal { local, .. }
        | Instruction::AddLocal { local, .. }
        | Instruction::Unary32 { local, .. }
        | Instruction::ReadScriptCell { local, .. }
        | Instruction::WriteScriptCell { local, .. }
        | Instruction::ReadControl { local, .. }
        | Instruction::WriteControl { local, .. }
        | Instruction::ReadGroupCount { local }
        | Instruction::WriteGroup {
            group: Some(local), ..
        }
        | Instruction::ReadControllerNumber { local }
        | Instruction::ReadControllerPort { local }
        | Instruction::ReadControllerGroup { local }
        | Instruction::ReadControllerChannel { local }
        | Instruction::ReadControllerValue { local }
        | Instruction::ControllerToMidi7 { local }
        | Instruction::ControllerFromMidi7 { local }
        | Instruction::ReadEventId { local }
        | Instruction::ReadCallbackId { local }
        | Instruction::ReadVelocity7 { local }
        | Instruction::WriteEventKey { local, .. }
        | Instruction::WriteEventVelocity7 { local, .. }
        | Instruction::MicrosToFrames { local }
        | Instruction::WaitLocal { local }
        | Instruction::WaitMicros { local }
        | Instruction::ReadKey { local }
        | Instruction::ReadKeyDown { local }
        | Instruction::ReadKeyHeld { local }
        | Instruction::ReadParameter { local, .. }
        | Instruction::ReadNoteCell { local, .. }
        | Instruction::WriteNoteCell { local, .. }
        | Instruction::JumpIfZero { local, .. } = *op
        {
            locals = locals.max(usize::from(local) + 1);
        }
        if let Instruction::PlayMidi {
            key,
            velocity,
            duration,
            offset_micros,
            result,
            ..
        } = *op
        {
            locals = locals.max(usize::from(key.max(velocity)) + 1);
            if let Some(offset) = offset_micros {
                locals = locals.max(usize::from(offset) + 1);
            }
            if let Some(result) = result {
                locals = locals.max(usize::from(result) + 1);
            }
            if let DurationValue::Frames(frames) = duration {
                locals = locals.max(usize::from(frames) + 1);
            }
        }
        if let Instruction::SendParameter { address, value, .. } = *op {
            locals = locals.max(usize::from(address.max(value)) + 1);
        }
        if let Instruction::CompareLocal { lhs, rhs, .. }
        | Instruction::Binary32 { lhs, rhs, .. } = *op
        {
            locals = locals.max(usize::from(lhs.max(rhs)) + 1);
        }

pub(crate) fn initialize_scripts(
    instrument: &mut ir::Instrument,
    library: Option<&Path>,
    groups: Vec<String>,
    control_values: &[(sampler_core::ControlId, i32)],
) -> ScriptInit {
    let resources = library.map(Resources::of).map(std::cell::RefCell::new);
    let mut views = Vec::new();
    let mut midi_object = sampler_core::MidiObject::default();
    let states = instrument
        .behaviors
        .iter()
        .enumerate()
        .map(|(index, behavior)| {
            let mut performance_view = Default::default();
            if let Some(name) = sampler_ksp::nckp::view_name(&behavior.source) {
                let path = format!("Resources/performance_view/{name}.nckp");
                let parsed = match resources.as_ref().and_then(|r| r.borrow_mut().read(&path)) {
                    Some(bytes) => sampler_ksp::nckp::parse(&bytes),
                    None => Err("not found in the library".into()),
                };
                match parsed {
                    Ok((view, skipped)) => {
                        performance_view = view;
                        views.extend(skipped.into_iter().map(|value| ir::Unsupported {
                            location: path.clone(),
                            feature: "performance view control".into(),
                            value,
                            reason: ir::Reason::NotModeled,
                        }));
                    }
                    Err(value) => views.push(ir::Unsupported {
                        location: behavior.name.clone(),
                        feature: "performance view".into(),
                        value: format!("{path}: {value}"),
                        reason: ir::Reason::InvalidValue,
                    }),
                }
            }
            let mut environment = script_environment(
                behavior,
                index,
                groups.clone(),
                &instrument.source_indices,
                &instrument.zones,
                performance_view,
            );

    initialize_scripts(
        instrument,
        options.library.as_deref(),
        groups,
        &options.control_values,
    )
});
